SourceCode.Declaration:
using Azure.Storage;
using Azure.Storage.Files.Shares;
using Azure.Storage.Files.Shares.Models;
using System.Threading;

/// <summary>
/// Handler class for importing files from an Azure file share including subdirectories
/// </summary>
class OMGInboundTransport_AzureFileShareSubDir extends OMGInboundTransport_AzureFileShare
{
}

Method.Source:
/// <summary>
/// Constructs the reader class
/// </summary>
/// <param name = "_dataContract">The data contract with the parameters to construct the class</param>
/// <returns>The constructed class</returns>
public OMGAzureFileShareReader constructReader(OMGInboundTransportContract _dataContract)
{
    return OMGAzureFileShareReader::newParameters(dataContract.parmKeyVaultCertificateRef(),
                                                  dataContract.parmFileShareName(),
                                                  dataContract.parmSourceDirectory(),
                                                  dataContract.parmArchiveDirectory(),
                                                  dataContract.parmFileTypeFilter(),
                                                  dataContract.parmPostImportAction(),
                                                  NoYes::Yes,
                                                  dataContract.parmArchiveUnderSourceDirectory(),
                                                  dataContract.parmArchiveFolderName());
}

/// <summary>
/// Description of class
/// </summary>
/// <returns>The description</returns>
public static Description description()
{
    return "@OMG:ImportFromAzureFileShareSubDir";
}
